module freq_div (
	input CLK_in, RST,
	output CLK_50, CLK_10, CLK_1
);
	// TODO: Please add your logic design here
	reg [2:0] cnt_10;
	reg [6:0] cnt_100;

	always@(posedge CLK_in or posedge RST) begin
		if(RST) begin
			cnt_10 <= 3'b0;
			cnt_100 <= 7'b0;
		end
		else begin
			cnt_10 <= cnt_10 + 1;
			cnt_100 <= cnt_100 + 1;
		end
	end

	assign CLK_50 = CLK_in;
	assign CLK_10 = cnt_10 == 3'd4 ? ~CLK_10 : CLK_10;
	assign CLK_1 = cnt_100 == 7'd49 ? ~CLK_1 : CLK_1;
endmodule
